/**
 *
 * TabsNext is the next navigation button for scrollable tabs.
 *
 * [Live Demo](https://www.primereact.org/tabs/)
 *
 * @module TabsNext
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { TabsRootInstance } from './TabsRoot.types';
/**
 * Defines passthrough(pt) options type in TabsNext component.
 */
export type TabsNextPassThroughType<E> = PassThroughType<TabsNextInstance, E>;
/**
 * Defines passthrough(pt) options of TabsNext component.
 */
export interface TabsNextPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: TabsNextPassThroughType<React.HTMLAttributes<HTMLButtonElement>>;
}
/**
 * Defines valid properties in TabsNext component.
 */
export interface TabsNextProps extends BaseComponentProps<TabsNextInstance, unknown, TabsNextPassThrough> {
    /**
     * Aria label for the next button.
     */
    ariaLabel?: string;
    /**
     * When enabled, the button is unmounted from the DOM when it is not needed.
     * @default false
     */
    lazy?: boolean;
}
/**
 * Defines valid state in TabsNext component.
 */
export interface TabsNextState {
}
/**
 * Defines the methods and properties exposed by TabsNext component.
 */
export interface TabsNextExposes {
    /**
     * The Tabs component instance.
     */
    tabs: TabsRootInstance | undefined | null;
}
/**
 * Instance of TabsNext component.
 */
export type TabsNextInstance = ComponentInstance<TabsNextProps, TabsNextState, TabsNextExposes>;
